#!/bin/bash
set -euo pipefail
test "$(id -u)" = 0
exec 9>/run/lock/agk-main-update.lock
flock -n 9
exec 8>/var/lock/agk-moderator.lock
flock -n 8
base=/var/www/agk-main
previous=$(readlink -f "$base/current")
case "$previous" in /var/www/agk-main/releases/*) ;; *) exit 1;; esac
test -f "$previous/mf_invite/index.html"
stamp=$(date -u +%Y%m%d-%H%M%S)-$$
backup=/var/backups/agk-main/speakers-$stamp
release=$base/releases/speakers-$stamp
mkdir -p "$backup"
printf '%s\n' "$previous" > "$backup/previous-release.txt"
python3 - "$previous" "$release" "$backup" <<'PY'
import sys,os,shutil,hashlib,json,base64,re
from pathlib import Path
old,new,backup=map(Path,sys.argv[1:])
assert old.is_dir() and old.parent==Path('/var/www/agk-main/releases') and not new.exists()
def manifest(root):
 return {str(f.relative_to(root)):hashlib.sha256(f.read_bytes()).hexdigest() for f in root.rglob('*') if f.is_file()}
before=manifest(old)
shutil.copytree(old,new,copy_function=os.link,symlinks=True)
files={'section.html': '', 'speakers-20261117.css': '', 'speaker-anastasia.webp': '', 'speaker-natalia.webp': ''}
section=base64.b64decode(files.pop('section.html')).decode('utf8')
path=new/'method-fest/index.html';s=path.read_text(encoding='utf8')
assert len(re.findall(r'<section id="s6".*?</section>',s,re.S))==1
s=re.sub(r'<section id="s6".*?</section>',lambda m:section,s,count=1,flags=re.S)
if 'speakers-20261117.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="speakers-20261117.css"></head>')
path.unlink();path.write_text(s,encoding='utf8');path.chmod(0o644)
allowed={'method-fest/index.html'}
for name,data in files.items():
 target='method-fest/'+('assets/' if name.endswith('.webp') else '')+name
 allowed.add(target);p=new/target
 if p.exists():p.unlink()
 p.write_bytes(base64.b64decode(data));p.chmod(0o644)
after=manifest(new)
assert {k:v for k,v in before.items() if k not in allowed}=={k:v for k,v in after.items() if k not in allowed}
assert before==manifest(old)
(backup/'before.json').write_text(json.dumps(before,sort_keys=True))
print('UNRELATED_FILES_IDENTICAL',len(before)-len(allowed))
PY
test "$(readlink -f "$base/current")" = "$previous"
switched=0
rollback(){ if test "$switched" = 1 && test "$(readlink -f "$base/current")" = "$release"; then ln -s "$previous" "$base/current.rollback-$stamp"; mv -Tf "$base/current.rollback-$stamp" "$base/current"; echo ROLLED_BACK; fi; }
trap rollback EXIT
ln -s "$release" "$base/current.invitation-$stamp"
mv -Tf "$base/current.invitation-$stamp" "$base/current"
switched=1
for path in method-fest/index.html method-fest/speakers-20261117.css method-fest/assets/speaker-anastasia.webp method-fest/assets/speaker-natalia.webp moderator/index.html mf_invite/index.html; do
 curl --retry 2 -fsSL --resolve agk-edu.ru:443:127.0.0.1 "https://agk-edu.ru/$path" -o "$backup/health-file"
 cmp "$backup/health-file" "$release/$path"
done
switched=0
trap - EXIT
echo SPEAKERS_DEPLOY_OK
echo "Backup: $backup"
systemctl is-active agk-method-fest-price.timer
